import{_ as o,a as n,c as s,ac as a}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"第一册：英语初阶 · 全册短语与句型 · 第112–137课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第一册：英语初阶 · 全册短语与句型 · 第112–137课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-1/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册短语与句型 · 第84–111课","link":"/life/english/new-concept/book-1/phrases-part-04"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第138–144课","link":"/life/english/new-concept/book-1/phrases-part-06"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册短语与句型 · 第84–111课","link":"/life/english/new-concept/book-1/phrases-part-04"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第138–144课","link":"/life/english/new-concept/book-1/phrases-part-06"}},"headers":[],"relativePath":"life/english/new-concept/book-1/phrases-part-05.md","filePath":"life/english/new-concept/book-1/phrases-part-05.md"}'),l={name:"life/english/new-concept/book-1/phrases-part-05.md"};function t(i,e,h,r,p,d){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="第一册-英语初阶-·-全册短语与句型-·-第112–137课" tabindex="-1">第一册：英语初阶 · 全册短语与句型 · 第112–137课 <a class="header-anchor" href="#第一册-英语初阶-·-全册短语与句型-·-第112–137课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册短语与句型 · 第112–137课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="lesson-112-·-形容词最高级" tabindex="-1">Lesson 112 · 形容词最高级 <a class="header-anchor" href="#lesson-112-·-形容词最高级" aria-label="Permalink to &quot;Lesson 112 · 形容词最高级 {#lesson-112-·-形容词最高级}&quot;">​</a></h2><ul><li>the most expensive — 最贵的</li><li>the best choice — 最佳选择</li></ul><p><strong>句型示范：</strong> Of the three routes, this one is the most convenient.</p><p>Of the three routes 提供三者范围；the most convenient 是多音节形容词最高级，one 指路线。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-112">进入本课</a></p><h2 id="lesson-113-·-so-neither-简短附和" tabindex="-1">Lesson 113 · so/neither 简短附和 <a class="header-anchor" href="#lesson-113-·-so-neither-简短附和" aria-label="Permalink to &quot;Lesson 113 · so/neither 简短附和 {#lesson-113-·-so-neither-简短附和}&quot;">​</a></h2><ul><li>so do I — 一般现在时肯定附和</li><li>neither can I — 能力否定附和</li></ul><p><strong>句型示范：</strong> I enjoy hiking, and so does my sister.</p><p>第一分句 enjoy 为一般现在时；附和中的主语 my sister 为单数，因此用 so does，而不是 so do。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-113">进入本课</a></p><h2 id="lesson-114-·-so-neither-简短附和" tabindex="-1">Lesson 114 · so/neither 简短附和 <a class="header-anchor" href="#lesson-114-·-so-neither-简短附和" aria-label="Permalink to &quot;Lesson 114 · so/neither 简短附和 {#lesson-114-·-so-neither-简短附和}&quot;">​</a></h2><ul><li>so do I — 一般现在时肯定附和</li><li>neither can I — 能力否定附和</li></ul><p><strong>句型示范：</strong> I cannot skate, and neither can Tom.</p><p>Cannot skate 是否定能力陈述；neither can Tom 用相同情态动词并倒装，表示汤姆也不能。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-114">进入本课</a></p><h2 id="lesson-115-·-复合不定代词" tabindex="-1">Lesson 115 · 复合不定代词 <a class="header-anchor" href="#lesson-115-·-复合不定代词" aria-label="Permalink to &quot;Lesson 115 · 复合不定代词 {#lesson-115-·-复合不定代词}&quot;">​</a></h2><ul><li>something useful — 形容词放后面</li><li>no one is — 不定代词按单数处理</li></ul><p><strong>句型示范：</strong> Someone is waiting at the side door.</p><p>Someone 作主语按单数处理，因此用 is waiting；at the side door 表等候位置。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-115">进入本课</a></p><h2 id="lesson-116-·-复合不定代词" tabindex="-1">Lesson 116 · 复合不定代词 <a class="header-anchor" href="#lesson-116-·-复合不定代词" aria-label="Permalink to &quot;Lesson 116 · 复合不定代词 {#lesson-116-·-复合不定代词}&quot;">​</a></h2><ul><li>something useful — 形容词放后面</li><li>no one is — 不定代词按单数处理</li></ul><p><strong>句型示范：</strong> There is nothing unusual in the box.</p><p>There is 引出 nothing；unusual 放在复合不定代词之后，nothing 已含否定，无需再加 not。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-116">进入本课</a></p><h2 id="lesson-117-·-过去进行时" tabindex="-1">Lesson 117 · 过去进行时 <a class="header-anchor" href="#lesson-117-·-过去进行时" aria-label="Permalink to &quot;Lesson 117 · 过去进行时 {#lesson-117-·-过去进行时}&quot;">​</a></h2><ul><li>was cooking — 当时正在做饭</li><li>when the phone rang — 电话响起这一事件</li></ul><p><strong>句型示范：</strong> I was making breakfast when the lights went out.</p><p>Was making 描写过去背景动作；when 引出的 went out 表停电事件。两者形成持续背景与突发事件的对照。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-117">进入本课</a></p><h2 id="lesson-118-·-过去进行时" tabindex="-1">Lesson 118 · 过去进行时 <a class="header-anchor" href="#lesson-118-·-过去进行时" aria-label="Permalink to &quot;Lesson 118 · 过去进行时 {#lesson-118-·-过去进行时}&quot;">​</a></h2><ul><li>was cooking — 当时正在做饭</li><li>when the phone rang — 电话响起这一事件</li></ul><p><strong>句型示范：</strong> They were waiting outside at eight yesterday.</p><p>Were waiting 与复数主语 they 一致；at eight yesterday 指过去特定时刻，说明那个时刻正在等。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-118">进入本课</a></p><h2 id="lesson-119-·-过去完成时" tabindex="-1">Lesson 119 · 过去完成时 <a class="header-anchor" href="#lesson-119-·-过去完成时" aria-label="Permalink to &quot;Lesson 119 · 过去完成时 {#lesson-119-·-过去完成时}&quot;">​</a></h2><ul><li>had already left — 在过去某时之前已经离开</li><li>by the time — 到……时为止</li></ul><p><strong>句型示范：</strong> By the time we arrived, the museum had closed.</p><p>We arrived 给出过去参照点；had closed 表博物馆关门发生得更早。by the time 强调到达时已有结果。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-119">进入本课</a></p><h2 id="lesson-120-·-过去完成时" tabindex="-1">Lesson 120 · 过去完成时 <a class="header-anchor" href="#lesson-120-·-过去完成时" aria-label="Permalink to &quot;Lesson 120 · 过去完成时 {#lesson-120-·-过去完成时}&quot;">​</a></h2><ul><li>had already left — 在过去某时之前已经离开</li><li>by the time — 到……时为止</li></ul><p><strong>句型示范：</strong> She had saved the file before the computer stopped.</p><p>Had saved 表先完成保存，stopped 表随后电脑停止；before 显式说明事件顺序。</p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-120">进入本课</a></p><h2 id="lesson-121-·-关系代词作主语" tabindex="-1">Lesson 121 · 关系代词作主语 <a class="header-anchor" href="#lesson-121-·-关系代词作主语" aria-label="Permalink to &quot;Lesson 121 · 关系代词作主语 {#lesson-121-·-关系代词作主语}&quot;">​</a></h2><ul><li>the person who — who 引导修饰人的定语从句，本课例句中 who 作从句主语</li><li>the book that — 修饰物的限制性从句</li></ul><p><strong>句型示范：</strong> The woman who lives upstairs is a violinist.</p><p>The woman 是先行词，who 在从句中作 lives 的主语，不能省略；主句谓语为 is。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-121">进入本课</a></p><h2 id="lesson-122-·-关系代词作主语" tabindex="-1">Lesson 122 · 关系代词作主语 <a class="header-anchor" href="#lesson-122-·-关系代词作主语" aria-label="Permalink to &quot;Lesson 122 · 关系代词作主语 {#lesson-122-·-关系代词作主语}&quot;">​</a></h2><ul><li>the person who — who 引导修饰人的定语从句，本课例句中 who 作从句主语</li><li>the book that — 修饰物的限制性从句</li></ul><p><strong>句型示范：</strong> The lamp that stands by the sofa is broken.</p><p>The lamp 是先行词，that 作 stands 的主语；by the sofa 是从句内位置说明，主句 is broken 说明状态。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-122">进入本课</a></p><h2 id="lesson-123-·-关系代词作宾语" tabindex="-1">Lesson 123 · 关系代词作宾语 <a class="header-anchor" href="#lesson-123-·-关系代词作宾语" aria-label="Permalink to &quot;Lesson 123 · 关系代词作宾语 {#lesson-123-·-关系代词作宾语}&quot;">​</a></h2><ul><li>the place we visited — 宾语关系代词可省略</li><li>during the journey — 旅程期间</li></ul><p><strong>句型示范：</strong> The guide we met in Perth spoke three languages.</p><p>The guide 是先行词；we met 中 we 为主语，被省略的关系代词是 met 的宾语；spoke 是主句谓语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-123">进入本课</a></p><h2 id="lesson-124-·-关系代词作宾语" tabindex="-1">Lesson 124 · 关系代词作宾语 <a class="header-anchor" href="#lesson-124-·-关系代词作宾语" aria-label="Permalink to &quot;Lesson 124 · 关系代词作宾语 {#lesson-124-·-关系代词作宾语}&quot;">​</a></h2><ul><li>the place we visited — 宾语关系代词可省略</li><li>during the journey — 旅程期间</li></ul><p><strong>句型示范：</strong> This is the photograph that I took at the harbour.</p><p>That 在从句 I took 中作宾语，可在这一限制性从句中省略；at the harbour 表拍照地点。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-124">进入本课</a></p><h2 id="lesson-125-·-have-to-的时态与否定" tabindex="-1">Lesson 125 · have to 的时态与否定 <a class="header-anchor" href="#lesson-125-·-have-to-的时态与否定" aria-label="Permalink to &quot;Lesson 125 · have to 的时态与否定 {#lesson-125-·-have-to-的时态与否定}&quot;">​</a></h2><ul><li>have to work — 因客观要求而必须工作</li><li>do not need to — 没有必要</li></ul><p><strong>句型示范：</strong> I had to water the plants before work.</p><p>Had to 是过去的客观必要，后接原形 water；plants 是宾语，before work 表发生时间。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-125">进入本课</a></p><h2 id="lesson-126-·-have-to-的时态与否定" tabindex="-1">Lesson 126 · have to 的时态与否定 <a class="header-anchor" href="#lesson-126-·-have-to-的时态与否定" aria-label="Permalink to &quot;Lesson 126 · have to 的时态与否定 {#lesson-126-·-have-to-的时态与否定}&quot;">​</a></h2><ul><li>have to work — 因客观要求而必须工作</li><li>do not need to — 没有必要</li></ul><p><strong>句型示范：</strong> She does not have to work this Sunday.</p><p>Does not have to 表第三人称单数的“不必”；have 恢复原形，this Sunday 指本次星期日。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-126">进入本课</a></p><h2 id="lesson-127-·-must-cannot-表现在推断" tabindex="-1">Lesson 127 · must/cannot 表现在推断 <a class="header-anchor" href="#lesson-127-·-must-cannot-表现在推断" aria-label="Permalink to &quot;Lesson 127 · must/cannot 表现在推断 {#lesson-127-·-must-cannot-表现在推断}&quot;">​</a></h2><ul><li>must be — 有根据的强推断</li><li>cannot be — 有根据地否定可能</li></ul><p><strong>句型示范：</strong> The office lights are on; someone must be inside.</p><p>前半句灯亮着是观察线索；后半句 must be 是强推断，someone 是主语，inside 为地点表语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-127">进入本课</a></p><h2 id="lesson-128-·-must-cannot-表现在推断" tabindex="-1">Lesson 128 · must/cannot 表现在推断 <a class="header-anchor" href="#lesson-128-·-must-cannot-表现在推断" aria-label="Permalink to &quot;Lesson 128 · must/cannot 表现在推断 {#lesson-128-·-must-cannot-表现在推断}&quot;">​</a></h2><ul><li>must be — 有根据的强推断</li><li>cannot be — 有根据地否定可能</li></ul><p><strong>句型示范：</strong> That cannot be our bus; it has a different number.</p><p>Cannot be 表不可能是；分号后 different number 提供推断依据，its number 与 expected bus number 不同。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-128">进入本课</a></p><h2 id="lesson-129-·-情态动词-have-done" tabindex="-1">Lesson 129 · 情态动词 + have done <a class="header-anchor" href="#lesson-129-·-情态动词-have-done" aria-label="Permalink to &quot;Lesson 129 · 情态动词 + have done {#lesson-129-·-情态动词-have-done}&quot;">​</a></h2><ul><li>must have missed — 推测过去一定错过</li><li>cannot have seen — 推测过去不可能看见</li></ul><p><strong>句型示范：</strong> The road is wet; it must have rained overnight.</p><p>The road is wet 是现在证据；must have rained 对过去下雨作推断，overnight 指夜里。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-129">进入本课</a></p><h2 id="lesson-130-·-情态动词-have-done" tabindex="-1">Lesson 130 · 情态动词 + have done <a class="header-anchor" href="#lesson-130-·-情态动词-have-done" aria-label="Permalink to &quot;Lesson 130 · 情态动词 + have done {#lesson-130-·-情态动词-have-done}&quot;">​</a></h2><ul><li>must have missed — 推测过去一定错过</li><li>cannot have seen — 推测过去不可能看见</li></ul><p><strong>句型示范：</strong> He cannot have read the sign; it was covered.</p><p>Cannot have read 对过去是否读到标志作否定推断；it was covered 给出证据，但推断本身不是亲眼观察。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-130">进入本课</a></p><h2 id="lesson-131-·-may-might-的时间层次" tabindex="-1">Lesson 131 · may/might 的时间层次 <a class="header-anchor" href="#lesson-131-·-may-might-的时间层次" aria-label="Permalink to &quot;Lesson 131 · may/might 的时间层次 {#lesson-131-·-may-might-的时间层次}&quot;">​</a></h2><ul><li>may be late — 现在或将来可能迟到</li><li>may have left — 过去可能已离开</li></ul><p><strong>句型示范：</strong> The parcel may arrive tomorrow.</p><p>May arrive 表未来可能，arrive 保持原形；tomorrow 表时间，整句不保证包裹一定到达。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-131">进入本课</a></p><h2 id="lesson-132-·-may-might-的时间层次" tabindex="-1">Lesson 132 · may/might 的时间层次 <a class="header-anchor" href="#lesson-132-·-may-might-的时间层次" aria-label="Permalink to &quot;Lesson 132 · may/might 的时间层次 {#lesson-132-·-may-might-的时间层次}&quot;">​</a></h2><ul><li>may be late — 现在或将来可能迟到</li><li>may have left — 过去可能已离开</li></ul><p><strong>句型示范：</strong> Ella might have left her phone on the train.</p><p>Might have left 对过去遗落手机作不确定推断；on the train 说明可能遗落的地点。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-132">进入本课</a></p><h2 id="lesson-133-·-间接引语的时态回移" tabindex="-1">Lesson 133 · 间接引语的时态回移 <a class="header-anchor" href="#lesson-133-·-间接引语的时态回移" aria-label="Permalink to &quot;Lesson 133 · 间接引语的时态回移 {#lesson-133-·-间接引语的时态回移}&quot;">​</a></h2><ul><li>said that — 过去转述</li><li>told us that — 告诉我们某事</li></ul><p><strong>句型示范：</strong> The reporter said that the bridge was closed.</p><p>Said 为过去引述，that 从句采用 was；the bridge 是从句主语，closed 为状态表语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-133">进入本课</a></p><h2 id="lesson-134-·-间接引语的时态回移" tabindex="-1">Lesson 134 · 间接引语的时态回移 <a class="header-anchor" href="#lesson-134-·-间接引语的时态回移" aria-label="Permalink to &quot;Lesson 134 · 间接引语的时态回移 {#lesson-134-·-间接引语的时态回移}&quot;">​</a></h2><ul><li>said that — 过去转述</li><li>told us that — 告诉我们某事</li></ul><p><strong>句型示范：</strong> Maya told us that she was studying abroad.</p><p>Told 后保留听话者 us；she was studying 是转述内容，其中过去进行时可对应原话的 am studying。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-134">进入本课</a></p><h2 id="lesson-135-·-would-与-had-done-的回移" tabindex="-1">Lesson 135 · would 与 had done 的回移 <a class="header-anchor" href="#lesson-135-·-would-与-had-done-的回移" aria-label="Permalink to &quot;Lesson 135 · would 与 had done 的回移 {#lesson-135-·-would-与-had-done-的回移}&quot;">​</a></h2><ul><li>would return — 过去视角的将来</li><li>the following day — 随后一天</li></ul><p><strong>句型示范：</strong> He said he would send the document the next day.</p><p>Would send 是过去视角中的将来；the next day 表相对于原说话日的第二天，不能随转述日期任意漂移。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-135">进入本课</a></p><h2 id="lesson-136-·-would-与-had-done-的回移" tabindex="-1">Lesson 136 · would 与 had done 的回移 <a class="header-anchor" href="#lesson-136-·-would-与-had-done-的回移" aria-label="Permalink to &quot;Lesson 136 · would 与 had done 的回移 {#lesson-136-·-would-与-had-done-的回移}&quot;">​</a></h2><ul><li>would return — 过去视角的将来</li><li>the following day — 随后一天</li></ul><p><strong>句型示范：</strong> She told me she had finished the repairs.</p><p>Told me 为主句，had finished 表相对于过去告诉我的时点已完成；the repairs 为从句宾语。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-136">进入本课</a></p><h2 id="lesson-137-·-真实条件句" tabindex="-1">Lesson 137 · 真实条件句 <a class="header-anchor" href="#lesson-137-·-真实条件句" aria-label="Permalink to &quot;Lesson 137 · 真实条件句 {#lesson-137-·-真实条件句}&quot;">​</a></h2><ul><li>if we finish — 未来条件用现在时</li><li>will take — 条件结果用将来表达</li></ul><p><strong>句型示范：</strong> If we finish early, we will take a walk.</p><p>If we finish early 为条件，用一般现在时；we will take a walk 为条件成立后的结果，用 will 加原形。</p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-137">进入本课</a></p>',133)])])}const g=o(l,[["render",t]]);export{c as __pageData,g as default};
